import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BEUshCVJ.js";const l=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1793315481000}'),i={name:"reference/faq.md"};function r(s,e,c,h,d,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Short answers to common questions. For problems, start at <a href="/meetcue/troubleshooting/">Troubleshooting</a>.</p><h2 id="does-meetcue-need-a-subscription" tabindex="-1">Does MeetCue need a subscription? <a class="header-anchor" href="#does-meetcue-need-a-subscription" aria-label="Permalink to &quot;Does MeetCue need a subscription?&quot;">​</a></h2><p>No. MeetCue is free and open source under the MIT license. You pay the speech and model providers directly, with your own keys, at their usual prices. Each provider&#39;s <strong>Official pricing</strong> link shows its current prices, and the settings show the actual usage afterwards.</p><h2 id="how-much-does-an-hour-of-meetings-cost" tabindex="-1">How much does an hour of meetings cost? <a class="header-anchor" href="#how-much-does-an-hour-of-meetings-cost" aria-label="Permalink to &quot;How much does an hour of meetings cost?&quot;">​</a></h2><p>It depends on the models you choose, and the difference can be dozens of times. A typical setup with a small model costs a few tens of US cents per hour, mostly for speech recognition. Check each provider&#39;s official pricing page, linked next to it in <strong>Settings › Providers &amp; cost</strong>; the latency probe also estimates the hourly cost of each combination. See also the <a href="/meetcue/reference/pricing">price reference</a>.</p><h2 id="can-the-other-participants-see-meetcue" tabindex="-1">Can the other participants see MeetCue? <a class="header-anchor" href="#can-the-other-participants-see-meetcue" aria-label="Permalink to &quot;Can the other participants see MeetCue?&quot;">​</a></h2><p>The panel is hidden from screen sharing and most recordings by default. Some recording methods and capture hardware can still see it; see <a href="/meetcue/troubleshooting/panel#screen-share">screen sharing</a>. MeetCue doesn&#39;t join the meeting or send anything to the meeting app.</p><h2 id="is-it-fair-to-use-meetcue-in-an-interview" tabindex="-1">Is it fair to use MeetCue in an interview? <a class="header-anchor" href="#is-it-fair-to-use-meetcue-in-an-interview" aria-label="Permalink to &quot;Is it fair to use MeetCue in an interview?&quot;">​</a></h2><p>That&#39;s for you and the situation to decide. Many interviews and exams don&#39;t allow outside help; follow the rules you agreed to. Practice mode is designed for preparing without any of these concerns.</p><h2 id="which-languages-are-supported" tabindex="-1">Which languages are supported? <a class="header-anchor" href="#which-languages-are-supported" aria-label="Permalink to &quot;Which languages are supported?&quot;">​</a></h2><p>The interface is in English and Simplified Chinese. Recognition and hints work in Chinese and English, including both in one sentence. Other languages may work with providers that support them, but aren&#39;t tested.</p><h2 id="does-it-work-on-macos-or-linux" tabindex="-1">Does it work on macOS or Linux? <a class="header-anchor" href="#does-it-work-on-macos-or-linux" aria-label="Permalink to &quot;Does it work on macOS or Linux?&quot;">​</a></h2><p>macOS 13 or later supports native system sound and microphone capture, Keychain credentials and system voices. Install the Apple Silicon or Intel app from Releases and grant microphone and screen/audio recording permissions. Linux can build the interface and run demo mode, but native audio capture is not implemented yet.</p><h2 id="can-i-use-a-model-running-on-my-own-computer" tabindex="-1">Can I use a model running on my own computer? <a class="header-anchor" href="#can-i-use-a-model-running-on-my-own-computer" aria-label="Permalink to &quot;Can I use a model running on my own computer?&quot;">​</a></h2><p>Yes, if it offers an OpenAI-compatible API with streaming. Enter its base URL under <a href="/meetcue/guide/providers#openai-compatible-apis">OpenAI-compatible APIs</a>. Speech recognition still needs one of the supported cloud services.</p><h2 id="why-does-meetcue-need-my-microphone" tabindex="-1">Why does MeetCue need my microphone? <a class="header-anchor" href="#why-does-meetcue-need-my-microphone" aria-label="Permalink to &quot;Why does MeetCue need my microphone?&quot;">​</a></h2><p>To know when you start and stop answering, to queue questions while you speak, and to tick off talking points you&#39;ve covered. Turn off <strong>Track what I&#39;ve said</strong> if you only want hints.</p>',18)])])}const m=a(i,[["render",r]]);export{l as __pageData,m as default};
